package checkpoint

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

const (
	// MaxChunkSize is the maximum size for a single transcript chunk.
	// GitHub has a 100MB limit per blob, so we use 50MB to be safe.
	MaxChunkSize = 50 * 1024 * 1024 // 50MB

	// ChunkSuffix is the format for chunk file suffixes (e.g., ".001", ".002")
	ChunkSuffix = ".%03d"
)

// ChunkTranscript splits a transcript into chunks if it exceeds MaxChunkSize.
// Returns a slice of chunks. If the transcript fits in one chunk, returns a single-element slice.
// The agentType determines how to split (JSONL at line boundaries, JSON at message boundaries).
func ChunkTranscript(content []byte, agentType string) ([][]byte, error) {
	if len(content) <= MaxChunkSize {
		return [][]byte{content}, nil
	}

	// Determine if this is Gemini JSON format
	isGemini := strings.Contains(agentType, "Gemini") || isGeminiJSONFormat(content)

	if isGemini {
		return chunkGeminiJSON(content)
	}
	return chunkJSONL(content)
}

// ReassembleTranscript combines chunks back into a single transcript.
// The agentType determines how to merge (JSONL concatenation, JSON message array merge).
func ReassembleTranscript(chunks [][]byte, agentType string) ([]byte, error) {
	if len(chunks) == 0 {
		return nil, nil
	}
	if len(chunks) == 1 {
		return chunks[0], nil
	}

	// Determine if this is Gemini JSON format by checking the first chunk
	isGemini := strings.Contains(agentType, "Gemini") || isGeminiJSONFormat(chunks[0])

	if isGemini {
		return reassembleGeminiJSON(chunks)
	}
	return reassembleJSONL(chunks), nil
}

// chunkJSONL splits JSONL content at line boundaries.
func chunkJSONL(content []byte) ([][]byte, error) {
	lines := strings.Split(string(content), "\n")
	var chunks [][]byte
	var currentChunk strings.Builder

	for _, line := range lines {
		// Check if adding this line would exceed the chunk size
		lineWithNewline := line + "\n"
		if currentChunk.Len()+len(lineWithNewline) > MaxChunkSize && currentChunk.Len() > 0 {
			// Save current chunk and start a new one
			chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
			currentChunk.Reset()
		}
		currentChunk.WriteString(lineWithNewline)
	}

	// Add the last chunk if it has content
	if currentChunk.Len() > 0 {
		chunks = append(chunks, []byte(strings.TrimSuffix(currentChunk.String(), "\n")))
	}

	return chunks, nil
}

// reassembleJSONL concatenates JSONL chunks with newlines.
func reassembleJSONL(chunks [][]byte) []byte {
	var result strings.Builder
	for i, chunk := range chunks {
		result.Write(chunk)
		if i < len(chunks)-1 {
			result.WriteString("\n")
		}
	}
	return []byte(result.String())
}

// geminiTranscript represents Gemini's JSON transcript format.
type geminiTranscript struct {
	Messages []json.RawMessage `json:"messages"`
}

// chunkGeminiJSON splits Gemini JSON by distributing messages across chunks.
func chunkGeminiJSON(content []byte) ([][]byte, error) {
	var transcript geminiTranscript
	if err := json.Unmarshal(content, &transcript); err != nil {
		// Fall back to JSONL chunking if not valid Gemini JSON
		return chunkJSONL(content)
	}

	if len(transcript.Messages) == 0 {
		return [][]byte{content}, nil
	}

	var chunks [][]byte
	var currentMessages []json.RawMessage
	currentSize := len(`{"messages":[]}`) // Base JSON structure size

	for _, msg := range transcript.Messages {
		msgSize := len(msg) + 1 // +1 for comma separator

		if currentSize+msgSize > MaxChunkSize && len(currentMessages) > 0 {
			// Save current chunk
			chunkData, err := json.Marshal(geminiTranscript{Messages: currentMessages})
			if err != nil {
				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
			}
			chunks = append(chunks, chunkData)

			// Start new chunk
			currentMessages = nil
			currentSize = len(`{"messages":[]}`)
		}

		currentMessages = append(currentMessages, msg)
		currentSize += msgSize
	}

	// Add the last chunk
	if len(currentMessages) > 0 {
		chunkData, err := json.Marshal(geminiTranscript{Messages: currentMessages})
		if err != nil {
			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
		}
		chunks = append(chunks, chunkData)
	}

	return chunks, nil
}

// reassembleGeminiJSON merges Gemini JSON chunks by combining their message arrays.
func reassembleGeminiJSON(chunks [][]byte) ([]byte, error) {
	var allMessages []json.RawMessage

	for _, chunk := range chunks {
		var transcript geminiTranscript
		if err := json.Unmarshal(chunk, &transcript); err != nil {
			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
		}
		allMessages = append(allMessages, transcript.Messages...)
	}

	return json.Marshal(geminiTranscript{Messages: allMessages})
}

// isGeminiJSONFormat detects if content is in Gemini's JSON format.
func isGeminiJSONFormat(content []byte) bool {
	trimmed := strings.TrimSpace(string(content))
	if !strings.HasPrefix(trimmed, "{") {
		return false
	}

	var transcript geminiTranscript
	if err := json.Unmarshal(content, &transcript); err != nil {
		return false
	}
	return len(transcript.Messages) > 0
}

// ChunkFileName returns the filename for a chunk at the given index.
// Index 0 returns the base filename, index 1+ returns with chunk suffix.
func ChunkFileName(baseName string, index int) string {
	if index == 0 {
		return baseName
	}
	return baseName + fmt.Sprintf(ChunkSuffix, index)
}

// ParseChunkIndex extracts the chunk index from a filename.
// Returns 0 for the base file (no suffix), or the chunk number for suffixed files.
// Returns -1 if the filename doesn't match the expected pattern.
func ParseChunkIndex(filename, baseName string) int {
	if filename == baseName {
		return 0
	}

	if !strings.HasPrefix(filename, baseName+".") {
		return -1
	}

	suffix := strings.TrimPrefix(filename, baseName+".")
	var index int
	if _, err := fmt.Sscanf(suffix, "%03d", &index); err != nil {
		return -1
	}
	return index
}

// SortChunkFiles sorts chunk filenames in order (base file first, then numbered chunks).
func SortChunkFiles(files []string, baseName string) []string {
	sorted := make([]string, len(files))
	copy(sorted, files)

	sort.Slice(sorted, func(i, j int) bool {
		idxI := ParseChunkIndex(sorted[i], baseName)
		idxJ := ParseChunkIndex(sorted[j], baseName)
		return idxI < idxJ
	})

	return sorted
}

