package checkpoint

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestChunkTranscript_SmallJSONL(t *testing.T) {
	// Small transcript should not be chunked
	content := []byte(`{"type":"human","message":"hello"}
{"type":"assistant","message":"hi"}`)

	chunks, err := ChunkTranscript(content, "Claude Code")
	if err != nil {
		t.Fatalf("ChunkTranscript error: %v", err)
	}
	if len(chunks) != 1 {
		t.Errorf("Expected 1 chunk, got %d", len(chunks))
	}
	if string(chunks[0]) != string(content) {
		t.Errorf("Chunk content mismatch")
	}
}

func TestChunkTranscript_LargeJSONL(t *testing.T) {
	// Create a transcript larger than MaxChunkSize
	var lines []string
	lineContent := `{"type":"human","message":"` + strings.Repeat("x", 1000) + `"}`
	// Calculate how many lines needed to exceed MaxChunkSize
	linesNeeded := (MaxChunkSize / len(lineContent)) + 100 // Extra to ensure multiple chunks

	for i := 0; i < linesNeeded; i++ {
		lines = append(lines, lineContent)
	}
	content := []byte(strings.Join(lines, "\n"))

	chunks, err := ChunkTranscript(content, "Claude Code")
	if err != nil {
		t.Fatalf("ChunkTranscript error: %v", err)
	}
	if len(chunks) < 2 {
		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
	}

	// Verify each chunk is under MaxChunkSize
	for i, chunk := range chunks {
		if len(chunk) > MaxChunkSize {
			t.Errorf("Chunk %d exceeds MaxChunkSize: %d > %d", i, len(chunk), MaxChunkSize)
		}
	}

	// Verify reassembly
	reassembled, err := ReassembleTranscript(chunks, "Claude Code")
	if err != nil {
		t.Fatalf("ReassembleTranscript error: %v", err)
	}
	if string(reassembled) != string(content) {
		t.Errorf("Reassembled content doesn't match original")
	}
}

func TestChunkTranscript_SmallGeminiJSON(t *testing.T) {
	// Small Gemini JSON should not be chunked
	content := []byte(`{"messages":[{"type":"user","content":"hello"},{"type":"model","content":"hi"}]}`)

	chunks, err := ChunkTranscript(content, "Gemini CLI")
	if err != nil {
		t.Fatalf("ChunkTranscript error: %v", err)
	}
	if len(chunks) != 1 {
		t.Errorf("Expected 1 chunk, got %d", len(chunks))
	}
}

func TestChunkTranscript_LargeGeminiJSON(t *testing.T) {
	// Create a large Gemini JSON transcript
	type message struct {
		Type    string `json:"type"`
		Content string `json:"content"`
	}
	type transcript struct {
		Messages []message `json:"messages"`
	}

	// Create many large messages
	var messages []message
	msgContent := strings.Repeat("x", 10000)
	messagesNeeded := (MaxChunkSize / len(msgContent)) + 100

	for i := 0; i < messagesNeeded; i++ {
		messages = append(messages, message{Type: "user", Content: msgContent})
	}

	content, err := json.Marshal(transcript{Messages: messages})
	if err != nil {
		t.Fatalf("Failed to marshal test data: %v", err)
	}

	chunks, err := ChunkTranscript(content, "Gemini CLI")
	if err != nil {
		t.Fatalf("ChunkTranscript error: %v", err)
	}
	if len(chunks) < 2 {
		t.Errorf("Expected at least 2 chunks for large content, got %d", len(chunks))
	}

	// Verify reassembly
	reassembled, err := ReassembleTranscript(chunks, "Gemini CLI")
	if err != nil {
		t.Fatalf("ReassembleTranscript error: %v", err)
	}

	// Parse both and compare message counts
	var original, reassembledTranscript transcript
	if err := json.Unmarshal(content, &original); err != nil {
		t.Fatalf("Failed to unmarshal original: %v", err)
	}
	if err := json.Unmarshal(reassembled, &reassembledTranscript); err != nil {
		t.Fatalf("Failed to unmarshal reassembled: %v", err)
	}
	if len(original.Messages) != len(reassembledTranscript.Messages) {
		t.Errorf("Message count mismatch: original %d, reassembled %d",
			len(original.Messages), len(reassembledTranscript.Messages))
	}
}

func TestChunkFileName(t *testing.T) {
	tests := []struct {
		baseName string
		index    int
		expected string
	}{
		{"full.jsonl", 0, "full.jsonl"},
		{"full.jsonl", 1, "full.jsonl.001"},
		{"full.jsonl", 2, "full.jsonl.002"},
		{"full.jsonl", 10, "full.jsonl.010"},
		{"full.jsonl", 100, "full.jsonl.100"},
	}

	for _, tt := range tests {
		result := ChunkFileName(tt.baseName, tt.index)
		if result != tt.expected {
			t.Errorf("ChunkFileName(%q, %d) = %q, want %q", tt.baseName, tt.index, result, tt.expected)
		}
	}
}

func TestParseChunkIndex(t *testing.T) {
	tests := []struct {
		filename string
		baseName string
		expected int
	}{
		{"full.jsonl", "full.jsonl", 0},
		{"full.jsonl.001", "full.jsonl", 1},
		{"full.jsonl.002", "full.jsonl", 2},
		{"full.jsonl.010", "full.jsonl", 10},
		{"full.jsonl.100", "full.jsonl", 100},
		{"other.txt", "full.jsonl", -1},
		{"full.jsonl.abc", "full.jsonl", -1},
	}

	for _, tt := range tests {
		result := ParseChunkIndex(tt.filename, tt.baseName)
		if result != tt.expected {
			t.Errorf("ParseChunkIndex(%q, %q) = %d, want %d", tt.filename, tt.baseName, result, tt.expected)
		}
	}
}

func TestSortChunkFiles(t *testing.T) {
	files := []string{"full.jsonl.003", "full.jsonl.001", "full.jsonl", "full.jsonl.002"}
	expected := []string{"full.jsonl", "full.jsonl.001", "full.jsonl.002", "full.jsonl.003"}

	sorted := SortChunkFiles(files, "full.jsonl")

	if len(sorted) != len(expected) {
		t.Fatalf("Length mismatch: got %d, want %d", len(sorted), len(expected))
	}
	for i, f := range sorted {
		if f != expected[i] {
			t.Errorf("Index %d: got %q, want %q", i, f, expected[i])
		}
	}
}

func TestIsGeminiJSONFormat(t *testing.T) {
	tests := []struct {
		name     string
		content  []byte
		expected bool
	}{
		{
			name:     "Gemini JSON",
			content:  []byte(`{"messages":[{"type":"user","content":"hi"}]}`),
			expected: true,
		},
		{
			name:     "JSONL",
			content:  []byte(`{"type":"human","message":"hi"}`),
			expected: false,
		},
