func TestReassembleTranscript_SingleChunk(t *testing.T) {
	content := []byte(`{"type":"human","message":"hello"}`)
	chunks := [][]byte{content}

	result, err := ReassembleTranscript(chunks, "Claude Code")
	if err != nil {
		t.Fatalf("ReassembleTranscript error: %v", err)
	}
	if string(result) != string(content) {
		t.Errorf("Content mismatch")
	}
}

func TestReassembleTranscript_EmptyChunks(t *testing.T) {
	result, err := ReassembleTranscript([][]byte{}, "Claude Code")
	if err != nil {
		t.Fatalf("ReassembleTranscript error: %v", err)
	}
	if result != nil {
		t.Errorf("Expected nil for empty chunks, got %v", result)
	}
}

